const fs = require('node:fs');
const path = require('node:path');
const sass = require('sass');
const postcss = require('postcss');
const postcssUrl = require('postcss-url');
const { fileURLToPath } = require('node:url');

const root = path.resolve(__dirname, '..');
const output = path.join(root, 'dist/vend-proofing-core/css');

function readCss(source) {
	// Supplied maps can refer to upstream source files absent from the package.
	const tree = postcss.parse(fs.readFileSync(source, 'utf8'), { from: source, map: { prev: false } });
	tree.walkComments((comment) => {
		if (/^#\s*sourceMappingURL=/.test(comment.text)) comment.remove();
	});
	return tree;
}

async function bundle(name, entry) {
	const filename = path.join(output, `${name}.css`);
	const result = sass.compile(path.join(root, entry.source), {
		style: 'expanded',
		charset: false,
		sourceMap: true,
	});
	const map = result.sourceMap;
	map.sources = map.sources.map((source) => path.relative(output, fileURLToPath(source)).split(path.sep).join('/'));
	const tree = postcss.root();
	for (const source of entry.prepend || []) tree.append(readCss(path.join(root, source)));
	tree.append(postcss.parse(result.css, { from: filename, map: { prev: map } }));
	for (const source of entry.append || []) tree.append(readCss(path.join(root, source)));

	const bundled = await postcss([postcssUrl({ url: 'rebase' })]).process(tree, {
		from: filename,
		to: filename,
		map: { inline: false, sourcesContent: false },
	});
	const bundledMap = bundled.map.toJSON();
	bundledMap.mappings = ';' + bundledMap.mappings;
	return [
		[filename, '/* Generated by npm run build:css. Edit src/ and assets.config.js instead. */\n' + bundled.css + '\n'],
		[filename + '.map', JSON.stringify(bundledMap) + '\n'],
	];
}

async function buildCss({ check = false } = {}) {
	// Reload configuration for a running watcher when prepend/append lists change.
	const configPath = path.join(root, 'assets.config.js');
	delete require.cache[require.resolve(configPath)];
	const { css } = require(configPath);
	// Finish every bundle before writing, so an error leaves the last build intact.
	const outputs = (await Promise.all(Object.entries(css).map(([name, entry]) => bundle(name, entry)))).flat();
	if (!check) fs.mkdirSync(output, { recursive: true });
	for (const [filename, contents] of outputs) {
		const existing = fs.existsSync(filename) ? fs.readFileSync(filename, 'utf8') : null;
		if (existing === contents) continue;
		if (check) throw new Error(`${filename} needs rebuilding: npm run build:css`);
		fs.writeFileSync(filename, contents);
	}
}

module.exports = { buildCss };
if (require.main === module) {
	buildCss({ check: process.argv.includes('--check') }).catch((error) => {
		console.error(error);
		process.exitCode = 1;
	});
}
